#include <iostream>
using namespace std;

struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int d) : data(d), left(nullptr), right(nullptr) {}
};

struct QNode {
    TreeNode* item;
    QNode* next;
};

void enqueue(QNode*& front, QNode*& rear, TreeNode* t) {
    QNode* n = new QNode();
    n->item = t;
    n->next = nullptr;
    if (rear == nullptr) {
        front = rear = n;
    } else {
        rear->next = n;
        rear = n;
    }
}

TreeNode* dequeue(QNode*& front, QNode*& rear) {
    QNode* old = front;
    TreeNode* t = old->item;
    front = front->next;
    if (front == nullptr) {
        rear = nullptr;
    }
    delete old;
    return t;
}

void levelOrder(TreeNode* root) {
    QNode* front = nullptr;
    QNode* rear = nullptr;
    enqueue(front, rear, root);
    while (front != nullptr) {
        TreeNode* cur = dequeue(front, rear);
        cout << cur->data << " ";
        if (cur->left != nullptr) {
            enqueue(front, rear, cur->left);
        }
        if (cur->right != nullptr) {
            enqueue(front, rear, cur->right);
        }
    }
    cout << endl;
}

void destroy(TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    TreeNode* root = new TreeNode(40);
    root->left = new TreeNode(20);
    root->right = new TreeNode(60);
    root->left->left = new TreeNode(10);
    root->left->right = new TreeNode(30);
    root->right->left = new TreeNode(50);
    levelOrder(root);
    destroy(root);
    return 0;
}
